<?php require 'config.php';require_login();if(($_SESSION['role']??'')!=='student'){exit('Students only.');}if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: jobs.php');exit;}$job=(int)($_POST['job_id']??0);$q=$pdo->prepare('SELECT id FROM jobs WHERE id=? AND (deadline IS NULL OR deadline>=CURDATE())');$q->execute([$job]);if(!$q->fetch()){exit('Job unavailable or deadline passed.');}try{$q=$pdo->prepare('INSERT INTO applications(user_id,job_id) VALUES(?,?)');$q->execute([$_SESSION['user_id'],$job]);}catch(PDOException $e){}header('Location: dashboard.php?applied=1');exit;?>